#!/usr/bin/env node
'use strict';

// Keep native stack capture lengths and barriers identical to the reference
// encoder. No allocated memory or per-call host lookup is needed for this ABI.
const fs = require('fs');
const path = require('path');
const { ARG_WORDS, BARRIERS } = require('../lib/gl-command-stream');
const OUTPUT = path.join(__dirname, '../src/09a8d-gl-abi.generated.wat');

function render() {
  const words = [...new Set(ARG_WORDS)].sort((a, b) => a - b);
  const lines = [
    ';; Generated by tools/gen-gl-encoder-abi.js; do not edit.',
    ';; Source: lib/gl-command-stream.js ARG_WORDS and BARRIERS.',
    '(func $gl_arg_words (param $op i32) (result i32)',
    '  (block $invalid',
  ];
  for (const n of [...words].reverse()) lines.push(`    (block $words${n}`);
  lines.push('      (br_table ' + ARG_WORDS.map(n => `$words${n}`).join(' ')
    + ' $invalid (local.get $op))');
  for (const n of words) lines.push(`    ) (return (i32.const ${n}))`);
  lines.push('  )', '  (i32.const -1))', '',
    '(func $gl_is_barrier (param $op i32) (result i32)',
    '  (block $no', '    (block $yes');
  lines.push('      (br_table ' + ARG_WORDS.map((_, i) => BARRIERS.has(i) ? '$yes' : '$no').join(' ')
    + ' $no (local.get $op))');
  lines.push('    ) (return (i32.const 1))', '  )', '  (i32.const 0))', '');
  return lines.join('\n');
}

function check() {
  return fs.existsSync(OUTPUT) && fs.readFileSync(OUTPUT, 'utf8') === render();
}

if (require.main === module) {
  if (process.argv.includes('--check')) {
    if (!check()) {
      console.error('GL encoder ABI is stale; run node tools/gen-gl-encoder-abi.js');
      process.exitCode = 1;
    } else console.log(`GL encoder ABI: OK (${ARG_WORDS.length} opcodes, ${BARRIERS.size} barriers)`);
  } else {
    fs.writeFileSync(OUTPUT, render());
    console.log(`Wrote ${path.relative(process.cwd(), OUTPUT)}`);
  }
}

module.exports = { render, check };
